# -*- coding: utf-8 -*-

# layout.py - migrated to PyQt6
#
# This file used to be generated by pyuic5 from layout.ui, with every widget
# placed with an absolute pixel geometry (setGeometry). That approach does
# not resize/adapt on large or small screens.
#
# It has been rewritten by hand to use real Qt layouts (QSplitter,
# QVBoxLayout, QHBoxLayout, QGridLayout, QFormLayout) so the whole window
# is responsive: panels grow/shrink with the window and the user can drag
# the splitter handles to rearrange space.
#
# All objectNames used by foxsample.py (self.ui.<name>) are preserved so
# the rest of the application code does not need to know how the widgets
# are arranged.

from PyQt6 import QtCore, QtGui, QtWidgets


class Ui_MainWindow(object):

    def setupUi(self, MainWindow):
        MainWindow.setObjectName("MainWindow")
        MainWindow.resize(1400, 1000)
        MainWindow.setMinimumSize(QtCore.QSize(900, 650))

        self.centralwidget = QtWidgets.QWidget(MainWindow)
        self.centralwidget.setObjectName("centralwidget")

        outer_layout = QtWidgets.QVBoxLayout(self.centralwidget)
        outer_layout.setObjectName("outer_layout")
        outer_layout.setContentsMargins(0, 0, 0, 0)

        expanding = QtWidgets.QSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding,
                                           QtWidgets.QSizePolicy.Policy.Expanding)

        # ------------------------------------------------------------------
        # Root splitter : everything else (left) | tools sidebar (right,
