        outer_layout.addWidget(self.root_splitter)

        left_widget = QtWidgets.QWidget(self.root_splitter)
        main_layout = QtWidgets.QVBoxLayout(left_widget)
        main_layout.setObjectName("main_layout")
        main_layout.setContentsMargins(0, 0, 0, 0)
        self.root_splitter.addWidget(left_widget)

        right_sidebar = self._build_right_sidebar()
