    def _build_right_sidebar(self):
        """Build the scrollable right sidebar: sample info, navigation,
        file actions, playback and FoxDot/library tools. Kept in a
        QScrollArea so it stays usable even on smaller window heights,
        while taking full advantage of the extra space on large screens."""

        scroll = QtWidgets.QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setObjectName("right_sidebar_scroll")
        scroll.setMinimumWidth(260)

        container = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(container)

        # --- Sample info ---------------------------------------------------
        info_group = QtWidgets.QGroupBox("Sample info")
        info_layout = QtWidgets.QVBoxLayout(info_group)
        self.verticalLayoutWidget = info_group  # kept for backward compat
        self.verticalLayout = info_layout

        self.label_channel = QtWidgets.QLabel(info_group)
        self.label_channel.setAutoFillBackground(False)
        self.label_channel.setFrameShape(QtWidgets.QFrame.Shape.Panel)
        self.label_channel.setObjectName("label_channel")
        info_layout.addWidget(self.label_channel)

        self.label_bytepersample = QtWidgets.QLabel(info_group)
        self.label_bytepersample.setFrameShape(QtWidgets.QFrame.Shape.Panel)
        self.label_bytepersample.setObjectName("label_bytepersample")
        info_layout.addWidget(self.label_bytepersample)

        self.label_samplerate = QtWidgets.QLabel(info_group)
        self.label_samplerate.setFrameShape(QtWidgets.QFrame.Shape.Panel)
        self.label_samplerate.setObjectName("label_samplerate")
        info_layout.addWidget(self.label_samplerate)

        self.label_duration = QtWidgets.QLabel(info_group)
        self.label_duration.setFrameShape(QtWidgets.QFrame.Shape.Panel)
        self.label_duration.setObjectName("label_duration")
        info_layout.addWidget(self.label_duration)

        self.label_dirName = QtWidgets.QLabel(info_group)
        self.label_dirName.setFrameShape(QtWidgets.QFrame.Shape.Panel)
        self.label_dirName.setObjectName("label_dirName")
        info_layout.addWidget(self.label_dirName)

        layout.addWidget(info_group)

        # --- Navigation (order within a bank) ------------------------------
        nav_group = QtWidgets.QGroupBox("Navigation")
        nav_layout = QtWidgets.QHBoxLayout(nav_group)
        self.horizontalLayoutWidget = nav_group
        self.horizontalLayout_2 = nav_layout

        self.Up_Button = QtWidgets.QToolButton(nav_group)
        self.Up_Button.setEnabled(True)
        self.Up_Button.setIconSize(QtCore.QSize(32, 32))
        self.Up_Button.setArrowType(QtCore.Qt.ArrowType.UpArrow)
        self.Up_Button.setObjectName("Up_Button")
        nav_layout.addWidget(self.Up_Button)

        self.line = QtWidgets.QFrame(nav_group)
        self.line.setFrameShape(QtWidgets.QFrame.Shape.VLine)
        self.line.setFrameShadow(QtWidgets.QFrame.Shadow.Sunken)
        self.line.setObjectName("line")
        nav_layout.addWidget(self.line)

        self.Down_Button = QtWidgets.QToolButton(nav_group)
        self.Down_Button.setIconSize(QtCore.QSize(32, 32))
        self.Down_Button.setAutoRaise(False)
        self.Down_Button.setArrowType(QtCore.Qt.ArrowType.DownArrow)
        self.Down_Button.setObjectName("Down_Button")
        nav_layout.addWidget(self.Down_Button)

        self.line_2 = QtWidgets.QFrame(nav_group)
        self.line_2.setFrameShape(QtWidgets.QFrame.Shape.VLine)
        self.line_2.setFrameShadow(QtWidgets.QFrame.Shadow.Sunken)
        self.line_2.setObjectName("line_2")
        nav_layout.addWidget(self.line_2)

        self.position_label = QtWidgets.QLCDNumber(nav_group)
        self.position_label.setLayoutDirection(QtCore.Qt.LayoutDirection.LeftToRight)
        self.position_label.setAutoFillBackground(False)
        self.position_label.setFrameShape(QtWidgets.QFrame.Shape.Panel)
        self.position_label.setFrameShadow(QtWidgets.QFrame.Shadow.Sunken)
        self.position_label.setLineWidth(0)
        self.position_label.setSmallDecimalPoint(False)
        self.position_label.setDigitCount(2)
        self.position_label.setSegmentStyle(QtWidgets.QLCDNumber.SegmentStyle.Filled)
        self.position_label.setProperty("value", 0.0)
        self.position_label.setProperty("intValue", 0)
        self.position_label.setObjectName("position_label")
        nav_layout.addWidget(self.position_label)

        self.verticalLayout_6 = QtWidgets.QVBoxLayout()
        self.verticalLayout_6.setObjectName("verticalLayout_6")
        self.swap_Button = QtWidgets.QPushButton(nav_group)
        self.swap_Button.setObjectName("swap_Button")
        self.verticalLayout_6.addWidget(self.swap_Button)
        self.swap_spinBox = QtWidgets.QSpinBox(nav_group)
        self.swap_spinBox.setObjectName("swap_spinBox")
        self.verticalLayout_6.addWidget(self.swap_spinBox)
        nav_layout.addLayout(self.verticalLayout_6)

        layout.addWidget(nav_group)

        # --- File actions ----------------------------------------------------
        actions_group = QtWidgets.QGroupBox("File actions")
        actions_layout = QtWidgets.QVBoxLayout(actions_group)
        self.verticalLayoutWidget_3 = actions_group
        self.verticalLayout_3 = actions_layout

        self.reindex_button = QtWidgets.QPushButton(actions_group)
        self.reindex_button.setObjectName("reindex_button")
        actions_layout.addWidget(self.reindex_button)
        self.rename_button = QtWidgets.QPushButton(actions_group)
        self.rename_button.setObjectName("rename_button")
        actions_layout.addWidget(self.rename_button)
        self.delete_button = QtWidgets.QPushButton(actions_group)
        self.delete_button.setCheckable(False)
        self.delete_button.setObjectName("delete_button")
        actions_layout.addWidget(self.delete_button)
        self.convert_button = QtWidgets.QPushButton(actions_group)
        self.convert_button.setObjectName("convert_button")
        actions_layout.addWidget(self.convert_button)

        layout.addWidget(actions_group)

        # --- Playback --------------------------------------------------------
        playback_group = QtWidgets.QGroupBox("Playback")
        playback_layout = QtWidgets.QVBoxLayout(playback_group)
        self.verticalLayoutWidget_4 = playback_group
        self.verticalLayout_4 = playback_layout

        self.horizontalLayout = QtWidgets.QHBoxLayout()
        self.horizontalLayout.setObjectName("horizontalLayout")
        self.volume_slider = QtWidgets.QSlider(playback_group)
        self.volume_slider.setMaximum(100)
        self.volume_slider.setProperty("value", 100)
        self.volume_slider.setOrientation(QtCore.Qt.Orientation.Horizontal)
        self.volume_slider.setInvertedAppearance(False)
        self.volume_slider.setObjectName("volume_slider")
        self.horizontalLayout.addWidget(self.volume_slider)
        self.Volume_label = QtWidgets.QLabel(playback_group)
        self.Volume_label.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.Volume_label.setObjectName("Volume_label")
        self.horizontalLayout.addWidget(self.Volume_label)
        playback_layout.addLayout(self.horizontalLayout)

        self.loop_checkbox = QtWidgets.QCheckBox(playback_group)
        self.loop_checkbox.setLayoutDirection(QtCore.Qt.LayoutDirection.LeftToRight)
        self.loop_checkbox.setAutoFillBackground(False)
        self.loop_checkbox.setChecked(False)
        self.loop_checkbox.setObjectName("loop_checkbox")
        playback_layout.addWidget(self.loop_checkbox)

        layout.addWidget(playback_group)

        # --- Transfer to/from library -----------------------------------------
        transfer_group = QtWidgets.QGroupBox("Transfer")
        transfer_layout = QtWidgets.QVBoxLayout(transfer_group)
        self.verticalLayoutWidget_5 = transfer_group
        self.verticalLayout_5 = transfer_layout

        self.copy_button = QtWidgets.QPushButton(transfer_group)
        self.copy_button.setObjectName("copy_button")
        transfer_layout.addWidget(self.copy_button)
        self.moveto_button = QtWidgets.QPushButton(transfer_group)
        self.moveto_button.setObjectName("moveto_button")
        transfer_layout.addWidget(self.moveto_button)

        layout.addWidget(transfer_group)

        # --- FoxDot / directory tools -------------------------------------
        foxdot_group = QtWidgets.QGroupBox("FoxDot")
        foxdot_layout = QtWidgets.QVBoxLayout(foxdot_group)
        self.verticalLayoutWidget_2 = foxdot_group
        self.verticalLayout_2 = foxdot_layout

        self.openfoxdot_button = QtWidgets.QPushButton(foxdot_group)
        self.openfoxdot_button.setObjectName("openfoxdot_button")
        foxdot_layout.addWidget(self.openfoxdot_button)
        self.make_dir_button = QtWidgets.QPushButton(foxdot_group)
        self.make_dir_button.setObjectName("make_dir_button")
        foxdot_layout.addWidget(self.make_dir_button)
        self.open_dir_button = QtWidgets.QPushButton(foxdot_group)
        self.open_dir_button.setObjectName("open_dir_button")
        foxdot_layout.addWidget(self.open_dir_button)
        self.open_source_dir_pushButton = QtWidgets.QPushButton(foxdot_group)
        self.open_source_dir_pushButton.setObjectName("open_source_dir_pushButton")
        foxdot_layout.addWidget(self.open_source_dir_pushButton)
        self.swap_dir_name_Button = QtWidgets.QPushButton(foxdot_group)
        self.swap_dir_name_Button.setObjectName("swap_dir_name_Button")
        foxdot_layout.addWidget(self.swap_dir_name_Button)

        layout.addWidget(foxdot_group)

        layout.addStretch(1)

        self.exit_button = QtWidgets.QPushButton(container)
        self.exit_button.setObjectName("exit_button")
        self.exit_button.setMinimumHeight(40)
        layout.addWidget(self.exit_button)

        scroll.setWidget(container)
        return scroll

